begin;
insert into public.permissions(code,description)values('applications.read','Read private program applications and authorized documents'),('applications.manage','Review and decide program applications'),('programs.operations.manage','Configure approved program intake, forms, places and on-site fees');
insert into public.role_permissions select r.id,p.id from public.roles r cross join public.permissions p where r.code in('platform_owner','operations_lead') and p.code in('applications.read','applications.manage','programs.operations.manage');
create table business_private.opportunity_assets(id uuid primary key default gen_random_uuid(),path text not null unique check(path ~ '^/opportunity-media/[a-zA-Z0-9_-]+\.(png|jpg|jpeg|webp|avif)$'),alt text not null check(length(btrim(alt)) between 1 and 240),sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),rights_reference text not null check(length(btrim(rights_reference)) between 1 and 240),approved boolean not null default false);
create table business_private.opportunities(
 id uuid primary key default gen_random_uuid(),slug text not null unique check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(slug)<=80),draft jsonb not null,public_content jsonb,
 operations jsonb not null default '{"duration":"","location":"","mode":null,"opensAt":null,"closesAt":null,"capacity":null,"feeXaf":null,"feeInstructions":""}',
 applications_open boolean not null default false,form_id uuid,version integer not null default 1 check(version>0),published_at timestamptz,updated_at timestamptz not null default now(),check(public_content is null or published_at is not null)
);
create table business_private.opportunity_forms(id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references business_private.opportunities(id) on delete restrict,version integer not null check(version>0),questions jsonb not null,created_at timestamptz not null default now(),unique(opportunity_id,version),unique(opportunity_id,id));
create function business_private.program_form_immutable()returns trigger language plpgsql set search_path='' as $$begin raise exception 'Application form versions cannot be overwritten' using errcode='42501';end;$$;
create trigger program_form_immutable before update on business_private.opportunity_forms for each row execute function business_private.program_form_immutable();
revoke all on function business_private.program_form_immutable()from public,anon,authenticated,service_role;
alter table business_private.opportunities add foreign key(id,form_id) references business_private.opportunity_forms(opportunity_id,id) on delete restrict;
create table business_private.program_applications(
 id uuid primary key default gen_random_uuid(),reference text not null unique check(reference ~ '^BWA-[a-f0-9]{32}$'),opportunity_id uuid not null references business_private.opportunities(id) on delete restrict,form_id uuid not null,
 opportunity_snapshot jsonb not null,full_name text not null,email text not null,whatsapp text,motivation text not null,answers jsonb not null,
 identity_hash bytea not null check(octet_length(identity_hash)=32),idempotency_hash bytea not null unique check(octet_length(idempotency_hash)=32),payload_hash bytea not null check(octet_length(payload_hash)=32),
 consent_version text not null check(consent_version='program-applications-v1'),status text not null default 'submitted' check(status in('submitted','under_review','shortlisted','accepted','rejected','withdrawn')),
 version integer not null default 1 check(version>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(opportunity_id,identity_hash),unique(id,opportunity_id),foreign key(opportunity_id,form_id) references business_private.opportunity_forms(opportunity_id,id) on delete restrict
);
create index program_applications_inbox on business_private.program_applications(opportunity_id,status,created_at desc);
create table business_private.program_reviews(id uuid primary key default gen_random_uuid(),application_id uuid not null references business_private.program_applications(id) on delete restrict,from_status text not null,to_status text not null,reason text not null check(length(btrim(reason)) between 1 and 1000),actor_id uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table business_private.program_enrollments(application_id uuid primary key,opportunity_id uuid not null,active boolean not null default true,accepted_at timestamptz not null default now(),withdrawn_at timestamptz,foreign key(application_id,opportunity_id)references business_private.program_applications(id,opportunity_id) on delete restrict,check((active and withdrawn_at is null) or(not active and withdrawn_at is not null)));
create table business_private.program_application_buckets(scope text not null check(scope in('global','email','opportunity')),key_hash bytea not null check(octet_length(key_hash)=32),window_start timestamptz not null,attempts integer not null check(attempts>0),primary key(scope,key_hash,window_start));
create table business_private.program_application_documents(
 id uuid primary key default gen_random_uuid(),application_id uuid not null references business_private.program_applications(id) on delete restrict,bucket_id text not null default 'program-application-documents' check(bucket_id='program-application-documents'),object_key text not null unique,
 display_name text not null check(length(display_name) between 1 and 200 and display_name !~ '[\r\n/\\]'),mime_type text not null check(mime_type in('application/pdf','image/jpeg','image/png')),size_bytes bigint not null check(size_bytes between 1 and 10485760),sha256_hex text not null check(sha256_hex ~ '^[a-f0-9]{64}$'),scan_status text not null default 'quarantined' check(scan_status in('quarantined','clean','rejected')),scanned_at timestamptz,created_at timestamptz not null default now(),check(object_key=application_id::text||'/'||id::text),check((scan_status='quarantined' and scanned_at is null)or(scan_status<>'quarantined' and scanned_at is not null))
);
revoke all on business_private.opportunity_assets,business_private.opportunities,business_private.opportunity_forms,business_private.program_applications,business_private.program_reviews,business_private.program_enrollments,business_private.program_application_buckets,business_private.program_application_documents from public,anon,authenticated,service_role;
do $$declare t text;begin foreach t in array array['opportunity_assets','opportunities','opportunity_forms','program_applications','program_reviews','program_enrollments','program_application_buckets','program_application_documents'] loop execute format('alter table business_private.%I enable row level security',t);execute format('create policy %I on business_private.%I as restrictive for all to authenticated using((select app_private.has_aal2_session())) with check((select app_private.has_aal2_session()))',t||'_mfa',t);end loop;end;$$;

create function business_private.valid_opportunity_copy(d jsonb)returns boolean language plpgsql stable set search_path='' as $$begin
 if d is null or jsonb_typeof(d)<>'object' or not d ?& array['title','description','kind','eligibility','requirements','coverId'] or(d-array['title','description','kind','eligibility','requirements','coverId'])<>'{}' then return false;end if;
 if jsonb_typeof(d->'title') is distinct from 'string' or not business_private.project_text(d->>'title',1,180) or jsonb_typeof(d->'description') is distinct from 'string' or not business_private.project_text(d->>'description',1,10000) or jsonb_typeof(d->'eligibility') is distinct from 'string' or not business_private.project_text(d->>'eligibility',0,4000) or jsonb_typeof(d->'requirements') is distinct from 'string' or not business_private.project_text(d->>'requirements',0,4000) or d->>'kind' is null or d->>'kind' not in('internship','training','workshop','other') then return false;end if;
 return d->'coverId'='null'::jsonb or(jsonb_typeof(d->'coverId')='string' and exists(select from business_private.opportunity_assets where id=(d->>'coverId')::uuid and approved));exception when invalid_text_representation then return false;end;$$;
create function business_private.valid_program_questions(q jsonb)returns boolean language plpgsql immutable set search_path='' as $$declare x jsonb;v jsonb;keys text[]:='{}';begin
 if q is null or jsonb_typeof(q)<>'array' or jsonb_array_length(q)>12 then return false;end if;
 for x in select * from jsonb_array_elements(q)loop
  if jsonb_typeof(x)<>'object' or not x ?& array['id','label','type','required','options'] or(x-array['id','label','type','required','options'])<>'{}' or x->>'id' is null or x->>'id' !~ '^[a-z][a-z0-9_]{0,39}$' or x->>'id'=any(keys) or jsonb_typeof(x->'label') is distinct from 'string' or not business_private.project_text(x->>'label',1,160) or x->>'type' is null or x->>'type' not in('short_text','long_text','single_choice','boolean') or jsonb_typeof(x->'required') is distinct from 'boolean' or jsonb_typeof(x->'options') is distinct from 'array' then return false;end if;
  keys:=array_append(keys,x->>'id');if x->>'type'='single_choice' then
   if jsonb_array_length(x->'options') not between 2 and 10 or jsonb_array_length(x->'options')<>(select count(distinct value)from jsonb_array_elements(x->'options')) then return false;end if;
   for v in select * from jsonb_array_elements(x->'options')loop if jsonb_typeof(v)<>'string' or not business_private.project_text(v#>>'{}',1,100) then return false;end if;end loop;
  elsif x->'options'<>'[]'::jsonb then return false;end if;
 end loop;return true;exception when invalid_parameter_value then return false;end;$$;
create function business_private.valid_program_answers(a jsonb,q jsonb)returns boolean language plpgsql immutable set search_path='' as $$declare x jsonb;v jsonb;k text;begin
 if a is null or jsonb_typeof(a)<>'object' then return false;end if;
 for k in select jsonb_object_keys(a)loop if not exists(select from jsonb_array_elements(q) as defs(question) where defs.question->>'id'=k)then return false;end if;end loop;
 for x in select * from jsonb_array_elements(q)loop v:=a->(x->>'id');if v is null or v='null'::jsonb or v='""'::jsonb then if(x->>'required')::boolean then return false;end if;continue;end if;
  case x->>'type' when 'short_text','long_text' then if jsonb_typeof(v)<>'string' or not business_private.project_text(v#>>'{}',1,case when x->>'type'='short_text' then 500 else 2000 end)then return false;end if;
  when 'single_choice' then if jsonb_typeof(v)<>'string' or not(x->'options' @> jsonb_build_array(v))then return false;end if;
  when 'boolean' then if jsonb_typeof(v)<>'boolean' then return false;end if;else return false;end case;
 end loop;return true;end;$$;
create function business_private.valid_program_operations(d jsonb)returns boolean language plpgsql stable set search_path='' as $$declare k text;o timestamptz;c timestamptz;begin
 if d is null or jsonb_typeof(d)<>'object' or not d ?& array['duration','location','mode','opensAt','closesAt','capacity','feeXaf','feeInstructions'] or(d-array['duration','location','mode','opensAt','closesAt','capacity','feeXaf','feeInstructions'])<>'{}' then return false;end if;
 foreach k in array array['duration','location','feeInstructions']loop if jsonb_typeof(d->k)<>'string' or not business_private.project_text(d->>k,0,case when k='feeInstructions' then 1000 else 500 end)then return false;end if;end loop;
 if d->'mode'<>'null'::jsonb and d->>'mode' not in('online','physical','hybrid')then return false;end if;
 foreach k in array array['capacity','feeXaf']loop if d->k<>'null'::jsonb and(jsonb_typeof(d->k)<>'number' or d->>k !~ '^[0-9]+$' or(d->>k)::numeric>case when k='capacity' then 100000 else 1000000000 end)then return false;end if;end loop;
 if coalesce((d->>'feeXaf')::numeric,0)>0 and length(btrim(d->>'feeInstructions'))=0 then return false;end if;
 foreach k in array array['opensAt','closesAt']loop if d->k<>'null'::jsonb and(jsonb_typeof(d->k)<>'string' or d->>k !~ '^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(\.\d{1,3})?Z$')then return false;end if;end loop;
 o:=(d->>'opensAt')::timestamptz;c:=(d->>'closesAt')::timestamptz;return(o is null or isfinite(o))and(c is null or isfinite(c))and(o is null or c is null or o<c);
 exception when invalid_text_representation or datetime_field_overflow or invalid_datetime_format then return false;end;$$;
create function business_private.opportunity_availability(o business_private.opportunities)returns text language sql stable set search_path='' as $$select case when o.public_content is null or not o.applications_open or o.form_id is null then 'closed' when(o.operations->>'opensAt')::timestamptz>now()then 'not_yet_open' when(o.operations->>'closesAt')::timestamptz<=now()then 'deadline_passed' when o.operations->>'capacity' is not null and(select count(*)from business_private.program_enrollments where opportunity_id=o.id and active)>=(o.operations->>'capacity')::int then 'full' else 'accepting' end$$;
create function business_private.opportunity_public_json(o business_private.opportunities)returns jsonb language sql stable set search_path='' as $$select o.public_content||jsonb_build_object('id',o.id,'slug',o.slug,'operations',o.operations,'availability',business_private.opportunity_availability(o),'formId',o.form_id,'questions',(select questions from business_private.opportunity_forms where id=o.form_id),'publishedAt',o.published_at,'cover',(select jsonb_build_object('id',id,'path',path,'alt',alt)from business_private.opportunity_assets where id=(o.public_content->>'coverId')::uuid and approved),'availablePlaces',case when o.operations->>'capacity' is null then null else greatest(0,(o.operations->>'capacity')::int-(select count(*)::int from business_private.program_enrollments where opportunity_id=o.id and active))end)$$;
create function public.list_published_opportunities()returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(business_private.opportunity_public_json(o)order by o.published_at desc,o.id),'[]'::jsonb)from business_private.opportunities o where public_content is not null and published_at<=now()$$;
create function public.get_published_opportunity(p_slug text)returns jsonb language sql stable security definer set search_path='' as $$select business_private.opportunity_public_json(o)from business_private.opportunities o where slug=p_slug and public_content is not null and published_at<=now()$$;
create function public.get_staff_opportunity(p_id uuid)returns jsonb language plpgsql stable security definer set search_path='' as $$declare o business_private.opportunities;begin
 if not app_private.has_aal2_session() or not(app_private.has_permission('content.read')or app_private.has_permission('programs.operations.manage'))then raise exception 'Access denied' using errcode='42501';end if;select * into o from business_private.opportunities where id=p_id;if not found then raise exception 'Opportunity unavailable';end if;
 return jsonb_build_object('id',o.id,'slug',o.slug,'draft',o.draft,'published',o.public_content is not null,'operations',o.operations,'applicationsOpen',o.applications_open,'formId',o.form_id,'questions',coalesce((select questions from business_private.opportunity_forms where id=o.form_id),'[]'::jsonb),'version',o.version,'availability',business_private.opportunity_availability(o))||case when app_private.has_permission('applications.read')then jsonb_build_object('applicationCount',(select count(*)from business_private.program_applications where opportunity_id=o.id),'acceptedCount',(select count(*)from business_private.program_enrollments where opportunity_id=o.id and active))else '{}'::jsonb end;end;$$;
create function public.list_staff_opportunities()returns jsonb language plpgsql stable security definer set search_path='' as $$begin if not app_private.has_aal2_session() or not(app_private.has_permission('content.read')or app_private.has_permission('programs.operations.manage'))then raise exception 'Access denied' using errcode='42501';end if;return(select coalesce(jsonb_agg(public.get_staff_opportunity(id)order by updated_at desc,id),'[]'::jsonb)from business_private.opportunities);end;$$;
create function public.list_opportunity_assets()returns jsonb language plpgsql stable security definer set search_path='' as $$begin perform business_private.require_permission('content.read');return(select coalesce(jsonb_agg(jsonb_build_object('id',id,'path',path,'alt',alt)order by path),'[]'::jsonb)from business_private.opportunity_assets where approved);end;$$;
create function public.save_opportunity_copy(p_id uuid,p_version int,p_slug text,p_copy jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare target uuid;begin perform business_private.require_permission('content.read');
 if p_slug is null or length(p_slug)>80 or p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or not business_private.valid_opportunity_copy(p_copy)then raise exception 'Invalid opportunity' using errcode='22023';end if;
 if p_id is null then perform business_private.require_permission('content.create');if p_version is distinct from 0 then raise exception 'Opportunity changed' using errcode='PT409';end if;insert into business_private.opportunities(slug,draft)values(p_slug,p_copy)returning id into target;
 else perform business_private.require_permission('content.update');update business_private.opportunities set draft=p_copy,version=version+1,updated_at=now()where id=p_id and version=p_version and slug=p_slug returning id into target;if not found then raise exception 'Opportunity changed or slug immutable' using errcode='PT409';end if;end if;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id)values(auth.uid(),'opportunity.copy_saved','opportunity',target::text);return public.get_staff_opportunity(target);exception when unique_violation then raise exception 'Slug unavailable' using errcode='PT409';end;$$;
create function public.publish_opportunity(p_id uuid,p_version int,p_published boolean)returns jsonb language plpgsql security definer set search_path='' as $$declare o business_private.opportunities;begin perform business_private.require_permission('content.read');perform business_private.require_permission('content.publish');select * into o from business_private.opportunities where id=p_id for update;if not found or o.version is distinct from p_version then raise exception 'Opportunity changed' using errcode='PT409';end if;
 if p_published is null or(p_published and not business_private.valid_opportunity_copy(o.draft))then raise exception 'Invalid publication' using errcode='22023';end if;
 update business_private.opportunities set public_content=case when p_published then draft else null end,applications_open=case when p_published then applications_open else false end,published_at=case when p_published then coalesce(published_at,now())else published_at end,version=version+1,updated_at=now()where id=p_id;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,metadata)values(auth.uid(),'opportunity.publication_changed','opportunity',p_id::text,jsonb_build_object('published',p_published));return public.get_staff_opportunity(p_id);end;$$;
create function public.configure_program(p_id uuid,p_version int,p_operations jsonb,p_questions jsonb,p_open boolean,p_attested boolean)returns jsonb language plpgsql security definer set search_path='' as $$declare o business_private.opportunities;target uuid;n int;begin perform business_private.require_permission('programs.operations.manage');select * into o from business_private.opportunities where id=p_id for update;if not found or o.version is distinct from p_version then raise exception 'Opportunity changed' using errcode='PT409';end if;
 if p_attested is distinct from true or p_open is null or not business_private.valid_program_operations(p_operations)or not business_private.valid_program_questions(p_questions)or(p_open and o.public_content is null)then raise exception 'Approved operational configuration required' using errcode='22023';end if;
 if p_operations->>'capacity' is not null and(p_operations->>'capacity')::int<(select count(*)from business_private.program_enrollments where opportunity_id=p_id and active)then raise exception 'Capacity below accepted places' using errcode='22023';end if;
 target:=o.form_id;if target is null or(select questions from business_private.opportunity_forms where id=target)is distinct from p_questions or o.operations is distinct from p_operations or o.applications_open is distinct from p_open then select coalesce(max(version),0)+1 into n from business_private.opportunity_forms where opportunity_id=p_id;insert into business_private.opportunity_forms(opportunity_id,version,questions)values(p_id,n,p_questions)returning id into target;end if;
 update business_private.opportunities set operations=p_operations,form_id=target,applications_open=p_open,version=version+1,updated_at=now()where id=p_id;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,metadata)values(auth.uid(),'program.configured','opportunity',p_id::text,jsonb_build_object('intakeEnabled',p_open,'formId',target));return public.get_staff_opportunity(p_id);end;$$;

create function public.submit_program_application(p_payload jsonb,p_reference text,p_identity_hex text,p_idempotency_hex text,p_payload_hex text,p_global_hex text,p_email_hex text,p_opportunity_hex text)returns void language plpgsql security definer set search_path='' as $$
declare o business_private.opportunities;q jsonb;a business_private.program_applications;k text;sc text;used int;lim int;target uuid;begin
 if p_payload is null or jsonb_typeof(p_payload)<>'object' or pg_column_size(p_payload)>40000 or not p_payload ?& array['opportunityId','formId','fullName','email','whatsapp','motivation','answers','consent','consentVersion']or(p_payload-array['opportunityId','formId','fullName','email','whatsapp','motivation','answers','consent','consentVersion'])<>'{}' or p_payload->'consent' is distinct from 'true'::jsonb or(p_payload->>'consentVersion')is distinct from 'program-applications-v1'
 or jsonb_typeof(p_payload->'fullName')is distinct from 'string' or not business_private.project_text(p_payload->>'fullName',1,160)or jsonb_typeof(p_payload->'email')is distinct from 'string' or length(p_payload->>'email')>254 or p_payload->>'email' !~ '^[a-zA-Z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-zA-Z0-9]([a-zA-Z0-9-]*[a-zA-Z0-9])?(\.[a-zA-Z0-9]([a-zA-Z0-9-]*[a-zA-Z0-9])?)+$'
 or jsonb_typeof(p_payload->'whatsapp')not in('string','null')or(p_payload->>'whatsapp' is not null and p_payload->>'whatsapp' !~ '^\+[1-9][0-9]{6,14}$')or jsonb_typeof(p_payload->'motivation')is distinct from 'string' or not business_private.project_text(p_payload->>'motivation',1,2000)or p_reference is null or p_reference !~ '^BWA-[a-f0-9]{32}$'then raise exception 'Invalid application' using errcode='22023';end if;
 foreach k in array array[p_identity_hex,p_idempotency_hex,p_payload_hex,p_global_hex,p_email_hex,p_opportunity_hex]loop if k is null or k !~ '^[a-f0-9]{64}$'then raise exception 'Invalid submission key' using errcode='22023';end if;end loop;
 perform pg_advisory_xact_lock(42045,1);
 foreach sc in array array['global','email','opportunity']loop k:=case sc when 'global'then p_global_hex when 'email'then p_email_hex else p_opportunity_hex end;lim:=case sc when 'global'then 100 when 'email'then 3 else 50 end;
  used:=null;insert into business_private.program_application_buckets(scope,key_hash,window_start,attempts)values(sc,decode(k,'hex'),date_trunc('hour',clock_timestamp()),1)on conflict(scope,key_hash,window_start)do update set attempts=business_private.program_application_buckets.attempts+1 where business_private.program_application_buckets.attempts<lim returning attempts into used;if used is null then raise exception 'Submission unavailable';end if;
 end loop;
 select * into a from business_private.program_applications where idempotency_hash=decode(p_idempotency_hex,'hex');if found then if a.payload_hash<>decode(p_payload_hex,'hex')or a.opportunity_id<>(p_payload->>'opportunityId')::uuid then raise exception 'Conflicting application' using errcode='22023';end if;return;end if;
 select * into o from business_private.opportunities where id=(p_payload->>'opportunityId')::uuid for update;
 if not found or business_private.opportunity_availability(o)<>'accepting' or o.form_id is distinct from(p_payload->>'formId')::uuid then raise exception 'Application unavailable' using errcode='22023';end if;
 select questions into q from business_private.opportunity_forms where id=o.form_id;if not business_private.valid_program_answers(p_payload->'answers',q)then raise exception 'Invalid answers' using errcode='22023';end if;
 insert into business_private.program_applications(reference,opportunity_id,form_id,opportunity_snapshot,full_name,email,whatsapp,motivation,answers,identity_hash,idempotency_hash,payload_hash,consent_version)
 values(p_reference,o.id,o.form_id,o.public_content||jsonb_build_object('operations',o.operations),btrim(p_payload->>'fullName'),lower(btrim(p_payload->>'email')),p_payload->>'whatsapp',btrim(p_payload->>'motivation'),p_payload->'answers',decode(p_identity_hex,'hex'),decode(p_idempotency_hex,'hex'),decode(p_payload_hex,'hex'),'program-applications-v1')on conflict(opportunity_id,identity_hash)do nothing returning id into target;
 if target is not null then insert into public.audit_logs(actor_id,action,resource_type,resource_id,metadata)values(null,'program.application_submitted','program_application',target::text,jsonb_build_object('opportunityId',o.id,'formId',o.form_id));end if;end;$$;
create function public.list_program_applications(p_opportunity uuid default null,p_status text default null,p_reference text default null)returns jsonb language plpgsql stable security definer set search_path='' as $$begin perform business_private.require_permission('applications.read');return(select coalesce(jsonb_agg(to_jsonb(x)order by created_at desc,id),'[]'::jsonb)from(select id,reference,opportunity_id,full_name,status,version,created_at,opportunity_snapshot->>'title' as opportunity_title from business_private.program_applications where(p_opportunity is null or opportunity_id=p_opportunity)and(p_status is null or status=p_status)and(p_reference is null or reference=p_reference)order by created_at desc,id limit 200)x);end;$$;
create function public.get_program_application(p_id uuid)returns jsonb language plpgsql stable security definer set search_path='' as $$declare a business_private.program_applications;begin perform business_private.require_permission('applications.read');select * into a from business_private.program_applications where id=p_id;if not found then raise exception 'Application unavailable';end if;
 return jsonb_build_object('id',a.id,'reference',a.reference,'opportunityId',a.opportunity_id,'opportunity',a.opportunity_snapshot,'fullName',a.full_name,'email',a.email,'whatsapp',a.whatsapp,'motivation',a.motivation,'answers',a.answers,'questions',(select questions from business_private.opportunity_forms where id=a.form_id),'status',a.status,'version',a.version,'createdAt',a.created_at,'reviews',(select coalesce(jsonb_agg(jsonb_build_object('from',from_status,'to',to_status,'reason',reason,'at',created_at)order by created_at,id),'[]'::jsonb)from business_private.program_reviews where application_id=a.id),'documents',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',display_name,'mime',mime_type,'bytes',size_bytes,'scanStatus',scan_status)order by created_at,id),'[]'::jsonb)from business_private.program_application_documents where application_id=a.id));end;$$;
create function public.review_program_application(p_id uuid,p_version int,p_status text,p_reason text)returns jsonb language plpgsql security definer set search_path='' as $$declare a business_private.program_applications;o business_private.opportunities;begin perform business_private.require_permission('applications.read');perform business_private.require_permission('applications.manage');
 select * into a from business_private.program_applications where id=p_id;if not found then raise exception 'Application unavailable';end if;select * into o from business_private.opportunities where id=a.opportunity_id for update;select * into a from business_private.program_applications where id=p_id for update;if a.version is distinct from p_version then raise exception 'Application changed' using errcode='PT409';end if;
 if p_status is null or not business_private.project_text(p_reason,1,1000)or not((a.status='submitted' and p_status in('under_review','withdrawn'))or(a.status='under_review' and p_status in('shortlisted','rejected','withdrawn'))or(a.status='shortlisted' and p_status in('accepted','rejected','withdrawn'))or(a.status='accepted' and p_status='withdrawn'))then raise exception 'Unsupported decision' using errcode='22023';end if;
 if p_status='accepted' then if o.operations->>'capacity' is not null and(select count(*)from business_private.program_enrollments where opportunity_id=o.id and active)>=(o.operations->>'capacity')::int then raise exception 'No available place' using errcode='22023';end if;insert into business_private.program_enrollments(application_id,opportunity_id)values(a.id,o.id);
 elsif p_status='withdrawn' and a.status='accepted' then update business_private.program_enrollments set active=false,withdrawn_at=now()where application_id=a.id;end if;
 insert into business_private.program_reviews(application_id,from_status,to_status,reason,actor_id)values(a.id,a.status,p_status,p_reason,auth.uid());update business_private.program_applications set status=p_status,version=version+1,updated_at=now()where id=p_id;
 insert into public.audit_logs(actor_id,action,resource_type,resource_id,metadata)values(auth.uid(),'program.application_reviewed','program_application',p_id::text,jsonb_build_object('from',a.status,'to',p_status));return public.get_program_application(p_id);end;$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('program-application-documents','program-application-documents',false,10485760,array['application/pdf','image/jpeg','image/png']);
create function business_private.can_read_program_document(p_key text)returns boolean language sql stable security definer set search_path='' as $$select app_private.has_aal2_session()and app_private.has_permission('applications.read')and exists(select from business_private.program_application_documents where object_key=p_key and scan_status='clean' and scanned_at is not null)$$;
create policy program_document_download on storage.objects for select to authenticated using(bucket_id='program-application-documents'and business_private.can_read_program_document(name));
create function public.authorize_program_document(p_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare d business_private.program_application_documents;begin perform business_private.require_permission('applications.read');select * into d from business_private.program_application_documents where id=p_id and scan_status='clean' and scanned_at is not null;if not found then raise exception 'Document unavailable' using errcode='42501';end if;insert into public.audit_logs(actor_id,action,resource_type,resource_id)values(auth.uid(),'program.document_download_authorized','program_document',p_id::text);return jsonb_build_object('bucket',d.bucket_id,'key',d.object_key);end;$$;
create function public.export_program_application_summary(p_opportunity uuid default null,p_status text default null,p_reference text default null)returns jsonb language plpgsql security definer set search_path='' as $$declare data jsonb;begin perform business_private.require_permission('applications.read');perform business_private.require_permission('documents.export');select coalesce(jsonb_agg(jsonb_build_object('reference',x->>'reference','opportunity_title',x->>'opportunity_title','status',x->>'status','created_at',x->>'created_at')),'[]'::jsonb)into data from jsonb_array_elements(public.list_program_applications(p_opportunity,p_status,p_reference))x;insert into public.audit_logs(actor_id,action,resource_type,metadata)values(auth.uid(),'program.summary_exported','program_application',jsonb_build_object('count',jsonb_array_length(data)));return data;end;$$;
revoke all on function public.export_program_application_summary(uuid,text,text)from public,anon,authenticated,service_role;grant execute on function public.export_program_application_summary(uuid,text,text)to authenticated;
revoke all on function business_private.valid_opportunity_copy(jsonb),business_private.valid_program_questions(jsonb),business_private.valid_program_answers(jsonb,jsonb),business_private.valid_program_operations(jsonb),business_private.opportunity_availability(business_private.opportunities),business_private.opportunity_public_json(business_private.opportunities) from public,anon,authenticated,service_role;
revoke all on function business_private.can_read_program_document(text)from public,anon,authenticated,service_role;grant execute on function business_private.can_read_program_document(text)to authenticated;
revoke all on function public.list_published_opportunities(),public.get_published_opportunity(text)from public,anon,authenticated,service_role;grant execute on function public.list_published_opportunities(),public.get_published_opportunity(text)to anon,authenticated;
revoke all on function public.get_staff_opportunity(uuid),public.list_staff_opportunities(),public.list_opportunity_assets(),public.save_opportunity_copy(uuid,int,text,jsonb),public.publish_opportunity(uuid,int,boolean),public.configure_program(uuid,int,jsonb,jsonb,boolean,boolean),public.list_program_applications(uuid,text,text),public.get_program_application(uuid),public.review_program_application(uuid,int,text,text),public.authorize_program_document(uuid)from public,anon,authenticated,service_role;
grant execute on function public.get_staff_opportunity(uuid),public.list_staff_opportunities(),public.list_opportunity_assets(),public.save_opportunity_copy(uuid,int,text,jsonb),public.publish_opportunity(uuid,int,boolean),public.configure_program(uuid,int,jsonb,jsonb,boolean,boolean),public.list_program_applications(uuid,text,text),public.get_program_application(uuid),public.review_program_application(uuid,int,text,text),public.authorize_program_document(uuid)to authenticated;
